window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-55d5acd3fa4d68a9"]={"versions": [{"id": "FIG-55d5acd3fa4d68a9", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML 2.0 Aktivitätsdiagramm (Activity Diagram).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Foundation / Classic Platform / Adaptive Platform, E2E Library (<code>E2E Protocol Specification</code>, Profil 11).</li>\n<li><strong>Funktionaler Zweck:</strong> Formale Spezifikation des atomaren Algorithmus-Schritts „Read Counter“ innerhalb der Prüffunktion <code>E2E_P11Check()</code>. Profil 11 dient der ASIL-D-konformen Erkennung von Übertragungsfehlern (Datenverlust, Wiederholung, Vertauschung, Einfügung) in sicherheitskritischen Kommunikationsbeziehungen über FlexRay, CAN-FD oder Ethernet. Der Schritt deserialisiert den empfangenen 4-Bit-Alive-Counter aus der Nutzdaten-PDU zur anschließenden Sequenzprüfung.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktionskontext:</strong> <code>E2E_P11Check()</code> (Funktionsrumpf der E2E-Bibliothek).</li>\n<li><strong>Strukturen & Parameter:</strong></li>\n<li><code>Config</code> (<code>const E2E_P11ConfigType*</code>): Enthält statische Metadaten, insbesondere <code>CounterOffset</code> (Bit-Offset des Zählers innerhalb des Datenstroms, Datentyp <code>uint16</code>).</li>\n<li><code>Data</code> (<code>const uint8*</code>): Zeiger auf den PDU-Empfangspuffer (Rohdatenarray).</li>\n<li><code>ReceivedCounter</code> (<code>uint8</code>): Lokale Zielvariable zur Aufnahme des normalisierten Zählerwerts ($0 \\dots 15$).</li>\n<li><strong>UML-Modellelemente:</strong></li>\n<li><em>Initial Node</em> (Startknoten) und <em>Activity Final Node</em> (Endknoten).</li>\n<li><em>Action Node</em>: Extraktionsanweisung des Nibbles in Little-Endian-Bitordnung.</li>\n<li><em>Comment / Note</em>: Formale Berechnungsformel, über gestrichelte Abhängigkeitslinie an die Aktion gebunden.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Trigger / Eintritt:</strong> Synchroner Aufruf innerhalb des Kontrollflusses von <code>E2E_P11Check()</code> nach erfolgreicher Validierung der Eingabeparameter (<code>Config != NULL</code>, <code>State != NULL</code>, <code>Data != NULL</code>).</li>\n<li><strong>Verarbeitungsschritte:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Byte-Index-Ermittlung:</strong> Berechnung des Zielbytes im Array via 3-Bit-Rechtsshift (Division durch 8):</li>\n</ol>\n<p class=\"fig-p\">$$\\text{Byte} = \\text{Data}[\\text{Config}\\to\\text{CounterOffset} \\gg 3]$$</p>\n<ol class=\"fig-list\">\n<li><strong>Bit-Extraktion & Normalisierung:</strong> Extraktion des 4-Bit-Nibbles durch Verschiebung um den bitweisen Rest ($\\text{Offset} \\pmod 8$) und Maskierung der unteren 4 Bits:</li>\n</ol>\n<p class=\"fig-p\">$$\\text{Counter} = (\\text{Byte} \\gg (\\text{Config}\\to\\text{CounterOffset} \\ \\& \\ 0\\text{x}7)) \\ \\& \\ 0\\text{x}0\\text{F}$$</p>\n<ol class=\"fig-list\">\n<li><strong>Zuweisung:</strong> Speicherung des Werts in <code>ReceivedCounter</code>.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Pfadcharakteristik:</strong> Rein deterministischer, linearer Pfad ohne Verzweigungen, Schleifen oder Callbacks (kein Aufruf von Det/Dem in diesem Einzelschritt).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Bindung:</strong> Verbindliche Implementierungsvorschrift gemäß <code>[PRS_E2E_00518]</code> zur Erfüllung von <code>[RS_E2E_08539]</code> (Absicherung gegen Sequenzfehler) und Schnittstelle zu Folgeschritten (<code>[PRS_E2E_00519]</code>).</li>\n<li><strong>Endianness & Alignment:</strong></li>\n<li>Die Formulierung „Little Endian order“ spezifiziert, dass Bit 0 das niederwertigste Bit (LSB) innerhalb des adressierten Speicherbereichs darstellt.</li>\n<li>Da das Nibble aus einem einzelnen <code>uint8</code> extrahiert wird, muss der gesamte 4-Bit-Bereich vollständig innerhalb desselben Bytes liegen ($(\\text{CounterOffset} \\ \\& \\ 0\\text{x}7) \\le 4$). In der Praxis ist <code>CounterOffset</code> typischerweise nibble-aligned ($0$ oder $4 \\pmod 8$).</li>\n<li><strong>Effizienz auf Embedded-Targets:</strong></li>\n<li>Der Ausdruck <code>(Byte &gt;&gt; (Offset &amp; 0x7)) &amp; 0x0F</code> lässt sich auf 32-Bit-RISC-Architekturen (z. B. ARM Cortex-R/M) direkt auf Hardware-Bitfeld-Extraktionsinstruktionen (<code>UBFX</code>) abbilden.</li>\n<li><strong>Folgezustand:</strong> Der extrahierte <code>ReceivedCounter</code> wird im unmittelbaren Nachfolgeschritt mit <code>State-&gt;Counter</code> verglichen (Berechnung von <code>DeltaCounter</code>), um den Status (<code>E2E_P11STATUS_OK</code>, <code>E2E_P11STATUS_REPEATED</code>, <code>E2E_P11STATUS_WRONGSEQUENCE</code>) zu ermitteln.</li>\n</ul>"}, {"id": "FIG-1fb2833830e1b5cd", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML 2.0 Aktivitätsdiagramm (Activity Diagram).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Foundation / Classic Platform / Adaptive Platform, E2E Library (<code>E2E Protocol Specification</code>, Profil 11).</li>\n<li><strong>Funktionaler Zweck:</strong> Formale Spezifikation des atomaren Algorithmus-Schritts „Read Counter“ innerhalb der Prüffunktion <code>E2E_P11Check()</code>. Profil 11 dient der ASIL-D-konformen Erkennung von Übertragungsfehlern (Datenverlust, Wiederholung, Vertauschung, Einfügung) in sicherheitskritischen Kommunikationsbeziehungen über FlexRay, CAN-FD oder Ethernet. Der Schritt deserialisiert den empfangenen 4-Bit-Alive-Counter aus der Nutzdaten-PDU zur anschließenden Sequenzprüfung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktionskontext:</strong> <code>E2E_P11Check()</code> (Funktionsrumpf der E2E-Bibliothek).</li>\n<li><strong>Strukturen & Parameter:</strong></li>\n<li><code>Config</code> (<code>const E2E_P11ConfigType*</code>): Enthält statische Metadaten, insbesondere <code>CounterOffset</code> (Bit-Offset des Zählers innerhalb des Datenstroms, Datentyp <code>uint16</code>).</li>\n<li><code>Data</code> (<code>const uint8*</code>): Zeiger auf den PDU-Empfangspuffer (Rohdatenarray).</li>\n<li><code>ReceivedCounter</code> (<code>uint8</code>): Lokale Zielvariable zur Aufnahme des normalisierten Zählerwerts ($0 \\dots 15$).</li>\n<li><strong>UML-Modellelemente:</strong></li>\n<li><em>Initial Node</em> (Startknoten) und <em>Activity Final Node</em> (Endknoten).</li>\n<li><em>Action Node</em>: Extraktionsanweisung des Nibbles in Little-Endian-Bitordnung.</li>\n<li><em>Comment / Note</em>: Formale Berechnungsformel, über gestrichelte Abhängigkeitslinie an die Aktion gebunden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Trigger / Eintritt:</strong> Synchroner Aufruf innerhalb des Kontrollflusses von <code>E2E_P11Check()</code> nach erfolgreicher Validierung der Eingabeparameter (<code>Config != NULL</code>, <code>State != NULL</code>, <code>Data != NULL</code>).</li>\n<li><strong>Verarbeitungsschritte:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Byte-Index-Ermittlung:</strong> Berechnung des Zielbytes im Array via 3-Bit-Rechtsshift (Division durch 8):</li>\n</ol>\n<p class=\"fig-p\">$$\\text{Byte} = \\text{Data}[\\text{Config}\\to\\text{CounterOffset} \\gg 3]$$</p>\n<ol class=\"fig-list\">\n<li><strong>Bit-Extraktion & Normalisierung:</strong> Extraktion des 4-Bit-Nibbles durch Verschiebung um den bitweisen Rest ($\\text{Offset} \\pmod 8$) und Maskierung der unteren 4 Bits:</li>\n</ol>\n<p class=\"fig-p\">$$\\text{Counter} = (\\text{Byte} \\gg (\\text{Config}\\to\\text{CounterOffset} \\ \\& \\ 0\\text{x}7)) \\ \\& \\ 0\\text{x}0\\text{F}$$</p>\n<ol class=\"fig-list\">\n<li><strong>Zuweisung:</strong> Speicherung des Werts in <code>ReceivedCounter</code>.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Pfadcharakteristik:</strong> Rein deterministischer, linearer Pfad ohne Verzweigungen, Schleifen oder Callbacks (kein Aufruf von Det/Dem in diesem Einzelschritt).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Bindung:</strong> Verbindliche Implementierungsvorschrift gemäß <code>[PRS_E2E_00518]</code> zur Erfüllung von <code>[RS_E2E_08539]</code> (Absicherung gegen Sequenzfehler) und Schnittstelle zu Folgeschritten (<code>[PRS_E2E_00519]</code>).</li>\n<li><strong>Endianness & Alignment:</strong></li>\n<li>Die Formulierung „Little Endian order“ spezifiziert, dass Bit 0 das niederwertigste Bit (LSB) innerhalb des adressierten Speicherbereichs darstellt.</li>\n<li>Da das Nibble aus einem einzelnen <code>uint8</code> extrahiert wird, muss der gesamte 4-Bit-Bereich vollständig innerhalb desselben Bytes liegen ($(\\text{CounterOffset} \\ \\& \\ 0\\text{x}7) \\le 4$). In der Praxis ist <code>CounterOffset</code> typischerweise nibble-aligned ($0$ oder $4 \\pmod 8$).</li>\n<li><strong>Effizienz auf Embedded-Targets:</strong></li>\n<li>Der Ausdruck <code>(Byte &gt;&gt; (Offset &amp; 0x7)) &amp; 0x0F</code> lässt sich auf 32-Bit-RISC-Architekturen (z. B. ARM Cortex-R/M) direkt auf Hardware-Bitfeld-Extraktionsinstruktionen (<code>UBFX</code>) abbilden.</li>\n<li><strong>Folgezustand:</strong> Der extrahierte <code>ReceivedCounter</code> wird im unmittelbaren Nachfolgeschritt mit <code>State-&gt;Counter</code> verglichen (Berechnung von <code>DeltaCounter</code>), um den Status (<code>E2E_P11STATUS_OK</code>, <code>E2E_P11STATUS_REPEATED</code>, <code>E2E_P11STATUS_WRONGSEQUENCE</code>) zu ermitteln.</li>\n</ul>"}, {"id": "FIG-e95c6dfba1099b13", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML 2.0 Aktivitätsdiagramm (Activity Diagram).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Foundation / Classic Platform / Adaptive Platform, E2E Library (<code>E2E Protocol Specification</code>, Profil 11).</li>\n<li><strong>Funktionaler Zweck:</strong> Formale Spezifikation des atomaren Algorithmus-Schritts „Read Counter“ innerhalb der Prüffunktion <code>E2E_P11Check()</code>. Profil 11 dient der ASIL-D-konformen Erkennung von Übertragungsfehlern (Datenverlust, Wiederholung, Vertauschung, Einfügung) in sicherheitskritischen Kommunikationsbeziehungen über FlexRay, CAN-FD oder Ethernet. Der Schritt deserialisiert den empfangenen 4-Bit-Alive-Counter aus der Nutzdaten-PDU zur anschließenden Sequenzprüfung.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktionskontext:</strong> <code>E2E_P11Check()</code> (Funktionsrumpf der E2E-Bibliothek).</li>\n<li><strong>Strukturen & Parameter:</strong></li>\n<li><code>Config</code> (<code>const E2E_P11ConfigType*</code>): Enthält statische Metadaten, insbesondere <code>CounterOffset</code> (Bit-Offset des Zählers innerhalb des Datenstroms, Datentyp <code>uint16</code>).</li>\n<li><code>Data</code> (<code>const uint8*</code>): Zeiger auf den PDU-Empfangspuffer (Rohdatenarray).</li>\n<li><code>ReceivedCounter</code> (<code>uint8</code>): Lokale Zielvariable zur Aufnahme des normalisierten Zählerwerts ($0 \\dots 15$).</li>\n<li><strong>UML-Modellelemente:</strong></li>\n<li><em>Initial Node</em> (Startknoten) und <em>Activity Final Node</em> (Endknoten).</li>\n<li><em>Action Node</em>: Extraktionsanweisung des Nibbles in Little-Endian-Bitordnung.</li>\n<li><em>Comment / Note</em>: Formale Berechnungsformel, über gestrichelte Abhängigkeitslinie an die Aktion gebunden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Trigger / Eintritt:</strong> Synchroner Aufruf innerhalb des Kontrollflusses von <code>E2E_P11Check()</code> nach erfolgreicher Validierung der Eingabeparameter (<code>Config != NULL</code>, <code>State != NULL</code>, <code>Data != NULL</code>).</li>\n<li><strong>Verarbeitungsschritte:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Byte-Index-Ermittlung:</strong> Berechnung des Zielbytes im Array via 3-Bit-Rechtsshift (Division durch 8):</li>\n</ol>\n<p class=\"fig-p\">$$\\text{Byte} = \\text{Data}[\\text{Config}\\to\\text{CounterOffset} \\gg 3]$$</p>\n<ol class=\"fig-list\">\n<li><strong>Bit-Extraktion & Normalisierung:</strong> Extraktion des 4-Bit-Nibbles durch Verschiebung um den bitweisen Rest ($\\text{Offset} \\pmod 8$) und Maskierung der unteren 4 Bits:</li>\n</ol>\n<p class=\"fig-p\">$$\\text{Counter} = (\\text{Byte} \\gg (\\text{Config}\\to\\text{CounterOffset} \\ \\& \\ 0\\text{x}7)) \\ \\& \\ 0\\text{x}0\\text{F}$$</p>\n<ol class=\"fig-list\">\n<li><strong>Zuweisung:</strong> Speicherung des Werts in <code>ReceivedCounter</code>.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Pfadcharakteristik:</strong> Rein deterministischer, linearer Pfad ohne Verzweigungen, Schleifen oder Callbacks (kein Aufruf von Det/Dem in diesem Einzelschritt).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Bindung:</strong> Verbindliche Implementierungsvorschrift gemäß <code>[PRS_E2E_00518]</code> zur Erfüllung von <code>[RS_E2E_08539]</code> (Absicherung gegen Sequenzfehler) und Schnittstelle zu Folgeschritten (<code>[PRS_E2E_00519]</code>).</li>\n<li><strong>Endianness & Alignment:</strong></li>\n<li>Die Formulierung „Little Endian order“ spezifiziert, dass Bit 0 das niederwertigste Bit (LSB) innerhalb des adressierten Speicherbereichs darstellt.</li>\n<li>Da das Nibble aus einem einzelnen <code>uint8</code> extrahiert wird, muss der gesamte 4-Bit-Bereich vollständig innerhalb desselben Bytes liegen ($(\\text{CounterOffset} \\ \\& \\ 0\\text{x}7) \\le 4$). In der Praxis ist <code>CounterOffset</code> typischerweise nibble-aligned ($0$ oder $4 \\pmod 8$).</li>\n<li><strong>Effizienz auf Embedded-Targets:</strong></li>\n<li>Der Ausdruck <code>(Byte &gt;&gt; (Offset &amp; 0x7)) &amp; 0x0F</code> lässt sich auf 32-Bit-RISC-Architekturen (z. B. ARM Cortex-R/M) direkt auf Hardware-Bitfeld-Extraktionsinstruktionen (<code>UBFX</code>) abbilden.</li>\n<li><strong>Folgezustand:</strong> Der extrahierte <code>ReceivedCounter</code> wird im unmittelbaren Nachfolgeschritt mit <code>State-&gt;Counter</code> verglichen (Berechnung von <code>DeltaCounter</code>), um den Status (<code>E2E_P11STATUS_OK</code>, <code>E2E_P11STATUS_REPEATED</code>, <code>E2E_P11STATUS_WRONGSEQUENCE</code>) zu ermitteln.</li>\n</ul>"}], "trans": [{"from": "FIG-55d5acd3fa4d68a9", "to": "FIG-1fb2833830e1b5cd", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><strong>Aktionsknoten / Textumbruch</strong>: In der Beschriftung der Aktion wurde der Zeilenumbruch von „Little Endian / order“ auf „Little / Endian order“ verschoben.</li>\n<li><strong>Kopfzeile</strong>: Die am oberen Bildrand zuvor fragmentarisch sichtbare Textzeile („behave as shown in Figure 6.109...“) wurde entfernt.</li>\n</ul>"}, {"from": "FIG-1fb2833830e1b5cd", "to": "FIG-e95c6dfba1099b13", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
